cd /tmp/probe && cat > extract.mjs <<'EOF'
import { readFileSync } from 'node:fs';
const lines = readFileSync('valid_currencies.tsv','utf8').split('\n').filter(Boolean);
const out = [];
const bad = [];
for (const line of lines) {
  const [code, formatted] = line.split('\t');
  // number rendered from 1234.56789 at N digits
  const m = formatted.match(/1,23[45](?:\.\d+)?$/);
  if (!m) { bad.push([code, formatted]); continue; }
  const num = m[0];
  const symbol = formatted.slice(0, formatted.length - num.length);
  const dot = num.indexOf('.');
  const digits = dot === -1 ? 0 : num.length - dot - 1;
  out.push({ code, symbol, digits, num });
}
console.log('BAD:', JSON.stringify(bad));
const byDigits = {};
for (const o of out) (byDigits[o.digits] ||= []).push(o.code);
for (const d of Object.keys(byDigits).sort()) console.log(`digits=${d} count=${byDigits[d].length}: ${byDigits[d].join(' ')}`);
// symbols that are not simply the code itself
const nonTrivial = out.filter(o => o.symbol !== o.code);
console.log('\nNON-TRIVIAL SYMBOLS ('+nonTrivial.length+'):');
for (const o of nonTrivial) {
  const esc = [...o.symbol].map(ch => ch.codePointAt(0) < 127 && ch.codePointAt(0) > 31 ? ch : '\\u'+o.symbol.codePointAt([...o.symbol].indexOf(ch)).toString(16).padStart(4,'0')).join('');
  console.log(`${o.code}\t${JSON.stringify(o.symbol)}\t${[...o.symbol].map(c=>'U+'+c.codePointAt(0).toString(16).toUpperCase().padStart(4,'0')).join(' ')}`);
}
console.log('\nTOTAL', out.length);
EOF
node extract.mjs

cd /tmp/probe && cat > gentable.mjs <<'EOF'
import { readFileSync, writeFileSync } from 'node:fs';
const lines = readFileSync('valid_currencies.tsv','utf8').split('\n').filter(Boolean);
const rows = [];
for (const line of lines) {
  const [code, formatted] = line.split('\t');
  const num = formatted.match(/1,23[45](?:\.\d+)?$/)[0];
  const symbol = formatted.slice(0, formatted.length - num.length);
  const dot = num.indexOf('.');
  rows.push({ code, symbol, digits: dot === -1 ? 0 : num.length - dot - 1 });
}
rows.sort((a,b)=>a.code<b.code?-1:1);
const esc = s => '"' + [...s].map(ch => {
  const cp = ch.codePointAt(0);
  if (ch === '"') return '\\"';
  if (ch === '\\') return '\\\\';
  return (cp >= 0x20 && cp < 0x7f) ? ch : '\\u' + cp.toString(16).toUpperCase().padStart(4,'0');
}).join('') + '"';

// Compact encoding: default digits = 2, default symbol = code.
const nonDefault = rows.filter(r => r.digits !== 2 || r.symbol !== r.code);
const plain = rows.filter(r => r.digits === 2 && r.symbol === r.code).map(r => r.code);

const chunk = (arr, n) => { const o=[]; for(let i=0;i<arr.length;i+=n) o.push(arr.slice(i,i+n)); return o; };
let s = '';
s += 'export const DEFAULT_DIGITS = 2;\n\n';
s += '// Currencies formatted in en_US with their ISO code as the symbol and 2 fraction digits.\n';
s += 'const CODE_AS_SYMBOL = [\n';
for (const c of chunk(plain, 12)) s += '  ' + c.map(x=>`'${x}'`).join(', ') + ',\n';
s += '].join(" ").split(" ");\n\n';
s += '// [code, en_US symbol, fraction digits] for every currency that deviates from the defaults.\n';
s += 'const OVERRIDES = [\n';
for (const r of nonDefault) s += `  ['${r.code}', ${esc(r.symbol)}, ${r.digits}],\n`;
s += '];\n';
writeFileSync('table_body.txt', s);
console.log('plain:', plain.length, 'overrides:', nonDefault.length);
console.log(s.slice(0, 400));
EOF
node gentable.mjs && echo "=== overrides ===" && grep -c "^  \['" table_body.txt

