/**
 * Error types mirroring the Python exceptions that can escape the original script,
 * plus the CPython-style traceback rendering used when they do.
 *
 * The reference program is a PyInstaller bundle, so an uncaught exception prints a
 * traceback whose frames carry no source lines, followed by the bootloader's
 * `[PYI-<pid>:ERROR] Failed to execute script 'test19' due to unhandled exception!`
 * line. Exit status is 1.
 */

/** Raised by `get_currency()` for a code the registry does not know. */
export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.name = 'CurrencyDoesNotExist';
    this.pyType = 'moneyed.classes.CurrencyDoesNotExist';
    this.code = code;
  }
}

/** Raised by the decimal context: NaN comparison, or quantize exceeding precision. */
export class InvalidOperation extends Error {
  constructor() {
    super("[<class 'decimal.InvalidOperation'>]");
    this.name = 'InvalidOperation';
    this.pyType = 'decimal.InvalidOperation';
  }
}

/**
 * Render a CPython traceback for `err` to stderr and terminate with status 1.
 *
 * `frames` is the innermost-last call stack, each entry `[file, line, func]`.
 * `cause` renders the "During handling of the above exception" chain that the
 * reference emits when CurrencyDoesNotExist is raised from a KeyError handler.
 */
export function abortWithTraceback(err, frames, cause) {
  const out = [];
  if (cause) {
    out.push('Traceback (most recent call last):');
    for (const [file, line, func] of cause.frames) {
      out.push(`  File "${file}", line ${line}, in ${func}`);
    }
    out.push(`${cause.pyType}: ${cause.message}`);
    out.push('');
    out.push('During handling of the above exception, another exception occurred:');
    out.push('');
  }
  out.push('Traceback (most recent call last):');
  for (const [file, line, func] of frames) {
    out.push(`  File "${file}", line ${line}, in ${func}`);
  }
  out.push(`${err.pyType}: ${err.message}`);
  process.stderr.write(out.join('\n') + '\n');
  process.stderr.write(
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test19' due to unhandled exception!\n`,
  );
  process.exit(1);
}

