/**
 * The slice of babel's CLDR data for locale `en_US` that currency formatting needs.
 *
 * The reference program resolves its locale from the environment (LC_ALL / LC_NUMERIC
 * / LANG) and the published test outputs — `€53.46`, `CA$204.37` — are en_US, which is
 * also what babel's `default_locale` falls back to. So the pattern below is fixed.
 */

/** `¤#,##0.00` — symbol first, no space, minus sign leading the whole thing. */
export const CURRENCY_PATTERN = Object.freeze({
  groupSize: 3,
  groupSeparator: ',',
  decimalSeparator: '.',
  minusSign: '-',
  /** en_US groups as soon as there are more digits than a group holds. */
  minimumGroupingDigits: 1,
});

/** CLDR `symbols/infinity` for en_US. */
export const INFINITY_SYMBOL = '∞';

/**
 * Insert `groupSeparator` every `groupSize` digits, right to left.
 * `digits` is an unsigned integer digit string.
 */
export function groupIntegerDigits(digits) {
  const { groupSize, groupSeparator, minimumGroupingDigits } = CURRENCY_PATTERN;
  if (digits.length <= groupSize + minimumGroupingDigits - 1) return digits;

  const head = digits.length % groupSize || groupSize;
  const parts = [digits.slice(0, head)];
  for (let i = head; i < digits.length; i += groupSize) {
    parts.push(digits.slice(i, i + groupSize));
  }
  return parts.join(groupSeparator);
}

