/**
 * babel's `format_currency(value, currency, locale='en_US')`, restricted to the
 * default (non-accounting, non-compact) format that `moneyed.l10n.format_money` asks for.
 *
 * babel splits the sign off first via `Decimal.is_signed()`, formats the magnitude,
 * then re-attaches the pattern's negative prefix. Reading the sign *before*
 * quantization is why `-0.001` renders as `-$0.00` rather than `$0.00`.
 */
import { isSigned, isInfinite, quantizeCoefficient } from './decimal.mjs';
import { CURRENCY_PATTERN, INFINITY_SYMBOL, groupIntegerDigits } from './locale.mjs';

/**
 * Render the magnitude of `value` with exactly `places` fraction digits.
 */
function formatMagnitude(value, places) {
  if (isInfinite(value)) return INFINITY_SYMBOL;

  const coefficient = quantizeCoefficient(value, places);
  const padded = coefficient.padStart(places + 1, '0');
  const integerDigits = padded.slice(0, padded.length - places);
  const grouped = groupIntegerDigits(integerDigits);

  if (places === 0) return grouped;
  return grouped + CURRENCY_PATTERN.decimalSeparator + padded.slice(padded.length - places);
}

/**
 * Format `value` (a Decimal) as `currency` for en_US.
 */
export function formatCurrency(value, currency) {
  const sign = isSigned(value) ? CURRENCY_PATTERN.minusSign : '';
  return sign + currency.symbol + formatMagnitude(value, currency.digits);
}

