/**
 * `moneyed.Money` — construction, ordering, and `__str__`.
 *
 * `Money(amount, currency)` stores `Decimal(str(amount))`, so a float argument keeps
 * its shortest round-tripping decimal value and no rounding happens until display.
 * Ordering therefore uses the full stored precision, not the rendered figure.
 */
import { decimalFromNumber, compare } from './decimal.mjs';
import { getCurrency } from './currencies.mjs';
import { formatCurrency } from './numbers.mjs';

export class Money {
  constructor(amount, currency) {
    this.amount = decimalFromNumber(amount);
    this.currency = getCurrency(currency);
  }

  /** `self.amount < other.amount`; raises InvalidOperation if either side is NaN. */
  lessThan(other) {
    return compare(this.amount, other.amount) < 0;
  }

  /** `str(money)` — delegates to `moneyed.l10n.format_money`. */
  toString() {
    return formatCurrency(this.amount, this.currency);
  }
}

