/**
 * `repr()` for Python strings, used by argparse in
 * `invalid float value: '...'`.
 *
 * CPython prefers single quotes, switching to double quotes only when the string
 * contains an apostrophe but no double quote. Control characters are escaped;
 * printable non-ASCII is emitted as-is.
 */

const SHORT_ESCAPES = { '\t': '\\t', '\n': '\\n', '\r': '\\r', '\\': '\\\\' };

export function pyRepr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (Object.hasOwn(SHORT_ESCAPES, ch)) {
      out += SHORT_ESCAPES[ch];
      continue;
    }
    if (ch === quote) {
      out += '\\' + ch;
      continue;
    }
    const cp = ch.codePointAt(0);
    if (cp < 0x20 || cp === 0x7f) {
      out += '\\x' + cp.toString(16).padStart(2, '0');
      continue;
    }
    out += ch;
  }
  return out + quote;
}

