 * declared, a token matching this is a value rather than an option, which is what
 * lets `--amount1 -5` work while `--currency -USD` does not.
 */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  if (token.length <= 1 || token[0] !== '-') return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  return !token.includes(' ');
}

export class ArgumentParser {
  /**
   * @param {string} prog name shown in usage and error lines
   */
  constructor(prog) {
    this.prog = prog;
    this.actions = [
      {
        dest: 'help',
        optionStrings: ['-h', '--help'],
        nargs: 0,
        required: false,
        help: 'show this help message and exit',
      },
    ];
  }

  addArgument(optionString, { type, required = false, metavar } = {}) {
    const dest = optionString.replace(/^--/, '').replace(/-/g, '_');
    this.actions.push({
      dest,
      optionStrings: [optionString],
      nargs: 1,
      required,
      type,
      metavar: metavar ?? dest.toUpperCase(),
      help: '',
    });
    return this;
  }

  /** `parser.error(message)`: usage + error line on stderr, exit 2. */
  error(message) {
    process.stderr.write(formatUsage(this.prog, this.actions) + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  printHelpAndExit() {
    process.stdout.write(formatHelp(this.prog, this.actions));
    process.exit(0);
  }

  /**
   * Resolve a long-option token to its action, honouring unique-prefix
   * abbreviation. Returns null when nothing matches.
   */
  #matchLongOption(flag, rawToken) {
    const candidates = [];
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) {
        if (optionString === flag) return { action, optionString };
        if (optionString.startsWith('--') && optionString.startsWith(flag)) {
          candidates.push({ action, optionString });
        }
      }
    }
    if (candidates.length > 1) {
      const names = candidates.map(c => c.optionString).join(', ');
      this.error(`ambiguous option: ${rawToken} could match ${names}`);
    }
    return candidates.length === 1 ? candidates[0] : null;
  }

  /**
   * Parse `argv` (the tokens after the program name) into a values object,
   * exiting the process on any error, exactly as argparse does.
   */
  parseArgs(argv) {
    const values = Object.create(null);
    const extras = [];
    let i = 0;

    while (i < argv.length) {
      const token = argv[i];

      if (token === '--') {
        // Everything after the first `--` is positional; this parser has none.
        extras.push(...argv.slice(i + 1));
        i = argv.length;
        break;
      }

      // `-h` and any `-h<rest>` bundle: the help action runs before extras are reported.
      if (/^-h/.test(token) && !token.startsWith('--')) {
        this.printHelpAndExit();
      }

      if (!token.startsWith('--') || token === '--') {
        extras.push(token);
        i += 1;
        continue;
      }

      const eq = token.indexOf('=');
      const flag = eq === -1 ? token : token.slice(0, eq);
      const explicitValue = eq === -1 ? null : token.slice(eq + 1);

      const match = this.#matchLongOption(flag, token);
      if (match === null) {
        extras.push(token);
        i += 1;
        continue;
      }
      const { action, optionString } = match;

      if (action.nargs === 0) {
        if (explicitValue !== null) {
          const names = action.optionStrings.join('/');
          this.error(`argument ${names}: ignored explicit argument ${pyRepr(explicitValue)}`);
        }
        this.printHelpAndExit();
      }

      let raw;
      if (explicitValue !== null) {
        raw = explicitValue;
        i += 1;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          this.error(`argument ${optionString}: expected one argument`);
        }
        raw = next;
        i += 2;
      }

      if (action.type) {
        const converted = action.type(raw);
        if (converted === null) {
          this.error(`argument ${optionString}: invalid float value: ${pyRepr(raw)}`);
        }
        values[action.dest] = converted;
      } else {
        values[action.dest] = raw;
      }
    }

    // Required options are reported before leftover tokens, in definition order.
    const missing = this.actions
      .filter(a => a.required && !(a.dest in values))
      .map(a => a.optionStrings.join('/'));
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }
}

