import { readFileSync, writeFileSync } from 'node:fs';
import { execFile } from 'node:child_process';

const cases = JSON.parse(readFileSync('cases.json', 'utf8'));
const EXE = '/workspace/dataset/test19_executable';
const ENV = { ...process.env, LANG: 'en_US.UTF-8', LC_ALL: 'en_US.UTF-8', COLUMNS: undefined };
delete ENV.COLUMNS;

const run = (cmd, argv) => new Promise(res => {
  execFile(cmd, argv, { env: ENV, encoding: 'buffer', maxBuffer: 1 << 26 }, (err, so, se) => {
    res({ code: err ? (err.code ?? 0) : 0, out: so.toString('utf8'), err: se.toString('utf8') });
  });
});

// The PyInstaller bootloader stamps its PID into the final stderr line; normalise it.
const norm = s => s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI:ERROR]');

const CONC = 24;
let idx = 0, mismatches = [], done = 0;
async function worker() {
  while (idx < cases.length) {
    const i = idx++;
    const argv = cases[i];
    const [py, js] = await Promise.all([run(EXE, argv), run(process.execPath, ['/output/test19.mjs', ...argv])]);
    const a = { code: py.code, out: py.out, err: norm(py.err) };
    const b = { code: js.code, out: js.out, err: norm(js.err) };
    if (a.out !== b.out || a.code !== b.code || a.err !== b.err) {
      mismatches.push({ argv, py: a, js: b,
        why: [a.out !== b.out && 'stdout', a.code !== b.code && 'exit', a.err !== b.err && 'stderr'].filter(Boolean) });
    }
    if (++done % 500 === 0) process.stderr.write(`  ${done}/${cases.length} (${mismatches.length} mismatch)\n`);
  }
}
await Promise.all(Array.from({ length: CONC }, worker));
writeFileSync('mismatches.json', JSON.stringify(mismatches, null, 1));
console.log(`\nTOTAL ${cases.length}  MISMATCHES ${mismatches.length}`);
const byKind = {};
for (const m of mismatches) byKind[m.why.join('+')] = (byKind[m.why.join('+')] || 0) + 1;
console.log(byKind);
for (const m of mismatches.slice(0, 25)) {
  console.log('\nARGV', JSON.stringify(m.argv), '->', m.why.join(','));
  console.log('  py:', JSON.stringify(m.py));
  console.log('  js:', JSON.stringify(m.js));
}
