/**
 * Usage and help rendering, following `argparse.HelpFormatter`.
 *
 * The wrapping is reproduced rather than hard-coded because the break point is
 * load-bearing: with a 17-character prog name the reference splits *between*
 * `--currency` and `CURRENCY`, since required options are printed unbracketed and
 * argparse's usage tokenizer treats a flag and its metavar as separate wrap tokens.
 */

/** argparse reads the terminal width and formats to `columns - 2`. */
function textWidth() {
  const columns = Number.parseInt(process.env.COLUMNS ?? '', 10);
  return (Number.isNaN(columns) ? 80 : columns) - 2;
}

/** `HelpFormatter._get_lines`: greedily pack parts, wrapping at the text width. */
function packLines(parts, indent, prefix) {
  const width = textWidth();
  const lines = [];
  let line = [];
  let lineLen = prefix.length - 1;

  for (const part of parts) {
    if (line.length && lineLen + 1 + part.length > width) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length) lines.push(indent + line.join(' '));
  if (lines.length) lines[0] = lines[0].slice(indent.length);
  return lines;
}

/** `'--amount1 AMOUNT1'` / `'-h, --help'` — how an option is shown. */
function invocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map(o => `${o} ${action.metavar}`).join(', ');
}

/** The `usage: ...` block, without a trailing newline. */
export function formatUsage(prog, actions) {
  const parts = [];
  for (const action of actions) {
    const text = action.required
      ? invocation(action)
      : `[${invocation(action)}]`;
    // argparse splits usage into bracketed groups and bare words; an unbracketed
    // `--currency CURRENCY` therefore contributes two independently wrappable tokens.
    parts.push(...(text.match(/\(.*?\)+|\[.*?\]+|\S+/g) || []));
  }

  const prefix = 'usage: ';
  const oneLine = `${prefix}${prog} ${parts.join(' ')}`;
  if (oneLine.length <= textWidth()) return oneLine;

  // Prog is short enough to keep on the first line and hang the rest under it.
  if (prefix.length + prog.length <= Math.floor(0.75 * textWidth())) {
    const indent = ' '.repeat(prefix.length + prog.length + 1);
    return prefix + packLines([prog, ...parts], indent, prefix).join('\n');
  }
  const indent = ' '.repeat(prefix.length);
  return `${prefix}${prog}\n` + packLines(parts, indent, indent).map(l => indent + l).join('\n');
}

/** The full `--help` text, with a trailing newline. */
export function formatHelp(prog, actions) {
  const indent = 2;
  const maxHelpPosition = 24;
  const invocations = actions.map(invocation);
  const actionMaxLength = Math.max(...invocations.map(i => i.length + indent));
  const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);

  const lines = [formatUsage(prog, actions), '', 'options:'];
  for (const [i, action] of actions.entries()) {
    const shown = ' '.repeat(indent) + invocations[i];
    if (!action.help) {
      lines.push(shown);
      continue;
    }
    if (shown.length < helpPosition) {
      lines.push(shown + ' '.repeat(helpPosition - shown.length) + action.help);
    } else {
      lines.push(shown, ' '.repeat(helpPosition) + action.help);
    }
  }
  return lines.join('\n') + '\n';
}

