  ['moneyed/classes.py', 203, '__str__'],
  ['moneyed/l10n.py', 23, 'format_money'],
  ['babel/numbers.py', 833, 'format_currency'],
  ['babel/numbers.py', 1547, 'apply'],
  ['babel/numbers.py', 1647, '_quantize_value'],
];

/** Run `body`, rendering a Python traceback and exiting 1 if it raises. */
function pythonFrame(frames, body, cause) {
  try {
    return body();
  } catch (err) {
    if (err instanceof CurrencyDoesNotExist || err instanceof InvalidOperation) {
