import { readFileSync, writeFileSync } from 'node:fs';
const codes = readFileSync('/tmp/probe/valid_currencies.tsv','utf8').trim().split('\n').map(l=>l.split('\t')[0]);
let s = 987654321;
const rnd = () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const cases = [];
const shapes = [
  () => String((rnd()*2-1) * Math.pow(10, Math.floor(rnd()*30)-8)),           // wide magnitude
  () => (rnd()*2000-1000).toFixed(Math.floor(rnd()*6)),                        // typical money
  () => ((Math.floor(rnd()*200000)*5)/100000).toFixed(5),                      // exact ties at 5 places
  () => ((Math.floor(rnd()*20000)*5)/1000).toFixed(3),                         // ties at 3 places
  () => ((Math.floor(rnd()*2000)*5)/10).toFixed(1),                            // ties at 1 place
  () => String(Math.floor(rnd()*1e15)),                                        // big integers
  () => (rnd()*1e-6).toPrecision(17),                                          // tiny, 17 sig digits
  () => (rnd()*1e26).toPrecision(17),                                          // near precision limit
  () => String(rnd()),                                                         // plain
];
for (let i = 0; i < 6000; i++) {
  const a = shapes[Math.floor(rnd()*shapes.length)]();
  const b = shapes[Math.floor(rnd()*shapes.length)]();
  const c = codes[Math.floor(rnd()*codes.length)];
  cases.push([`--amount1=${a}`, `--amount2=${b}`, '--currency', c]);
}
writeFileSync('cases.json', JSON.stringify(cases));
