/**
 * Python's `float(str)` conversion, reimplemented for `argparse(type=float)`.
 *
 * CPython does this in two steps, and both matter:
 *
 *   1. `_PyUnicode_TransformDecimalAndSpaceToASCII` rewrites the string — ASCII is
 *      passed through untouched, non-ASCII whitespace collapses to a plain space,
 *      and any Unicode decimal digit folds to its ASCII equivalent (so `١٢٣` is a
 *      perfectly good `123`). Anything else non-ASCII poisons the string.
 *   2. `float_from_string_inner` strips *ASCII* whitespace and runs strtod.
 *
 * The split explains two behaviours a single trim would get wrong: U+00A0 is
 * accepted as padding (step 1 turns it into a space) while U+001C is rejected
 * (it is ASCII, so step 1 leaves it alone and step 2 does not consider it space).
 */

/** `Py_UNICODE_ISSPACE` restricted to the non-ASCII code points, used by step 1. */
function isUnicodeSpace(cp) {
  return (
    cp === 0x85 ||
    cp === 0xa0 ||
    cp === 0x1680 ||
    (cp >= 0x2000 && cp <= 0x200a) ||
    cp === 0x2028 ||
    cp === 0x2029 ||
    cp === 0x202f ||
    cp === 0x205f ||
    cp === 0x3000
  );
}

const DECIMAL_DIGIT = /\p{Nd}/u;

/**
 * `Py_UNICODE_TODECIMAL`: the 0-9 value of a Unicode decimal digit, or -1.
 *
 * Every Nd run in Unicode is a whole number of consecutive 0-9 sequences, so the
 * value is the offset from the start of the run, modulo ten. (Verified against the
 * full code space: all 64 runs have a length divisible by 10.)
 */
function decimalDigitValue(ch) {
  if (!DECIMAL_DIGIT.test(ch)) return -1;
  const cp = ch.codePointAt(0);
  let runStart = cp;
  while (runStart > 0 && DECIMAL_DIGIT.test(String.fromCodePoint(runStart - 1))) runStart--;
  return (cp - runStart) % 10;
}

/** Step 1. Returns null when a character cannot be represented in ASCII. */
function transformDecimalAndSpaceToASCII(text) {
  let out = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 127) {
      out += ch;
    } else if (isUnicodeSpace(cp)) {
      out += ' ';
    } else {
      const value = decimalDigitValue(ch);
      if (value < 0) return null;
      out += String(value);
    }
  }
  return out;
}

/** `Py_ISSPACE`: the six ASCII whitespace characters strtod skips. */
const ASCII_SPACE = ' \t\n\v\f\r';

function stripAsciiSpace(s) {
  let a = 0;
  let b = s.length;
  while (a < b && ASCII_SPACE.includes(s[a])) a++;
  while (b > a && ASCII_SPACE.includes(s[b - 1])) b--;
  return s.slice(a, b);
}

/**
 * Drop PEP 515 underscores, or return null if any underscore is not flanked by
 * digits on both sides (`1_000` is fine, `_1`, `1_`, `1__0`, `1_.0` are not).
 */
function removeUnderscores(s) {
  if (!s.includes('_')) return s;
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== '_') continue;
    const prev = s[i - 1];
    const next = s[i + 1];
    if (prev === undefined || next === undefined) return null;
    if (prev < '0' || prev > '9' || next < '0' || next > '9') return null;
  }
  return s.replace(/_/g, '');
}

// digits[.digits] | .digits  — with an optional decimal exponent.
const DECIMAL_RE = /^(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

/**
 * Parse `text` the way CPython's `float()` does.
 * Returns a JS number, or null when CPython would raise ValueError.
 */
export function pyFloat(text) {
  const ascii = transformDecimalAndSpaceToASCII(text);
  if (ascii === null) return null;

  const stripped = stripAsciiSpace(ascii);
  if (stripped === '') return null;

  let sign = 1;
  let body = stripped;
  if (body[0] === '+' || body[0] === '-') {
    if (body[0] === '-') sign = -1;
    body = body.slice(1);
  }
  if (body === '') return null;

  const lowered = body.toLowerCase();
  if (lowered === 'inf' || lowered === 'infinity') return sign * Infinity;
  if (lowered === 'nan') return sign * NaN;

  const cleaned = removeUnderscores(body);
  if (cleaned === null || !DECIMAL_RE.test(cleaned)) return null;

  // The regex has already excluded every form Number() would treat leniently
  // (empty string, hex, whitespace, "Infinity"), so this is a faithful strtod.
  return sign * Number(cleaned);
}

