/**
 * `repr()` for Python strings, used by argparse in
 * `invalid float value: '...'` and by the chained `KeyError` in the traceback.
 *
 * CPython prefers single quotes, switching to double quotes only when the string
 * contains an apostrophe but no double quote. Printable characters — including
 * non-ASCII ones like `é` and emoji — are emitted verbatim; everything Python
 * considers non-printable becomes a lowercase hex escape sized to the code point.
 */

const SHORT_ESCAPES = { '\t': '\\t', '\n': '\\n', '\r': '\\r', '\\': '\\\\' };

/**
 * The complement of `str.isprintable()`: the Unicode categories C* and Z*,
 * except that a plain space is printable.
 */
const NON_PRINTABLE = /[\p{C}\p{Zl}\p{Zp}\p{Zs}]/u;

function hexEscape(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

export function pyRepr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (Object.hasOwn(SHORT_ESCAPES, ch)) {
      out += SHORT_ESCAPES[ch];
    } else if (ch === quote) {
      out += '\\' + ch;
    } else if (ch !== ' ' && NON_PRINTABLE.test(ch)) {
      out += hexEscape(ch.codePointAt(0));
    } else {
      out += ch;
    }
  }
  return out + quote;
}

