                 '--help', '--help=x', '--help=', '--h', '--he', '--hel', '-h0', '-h5']) {
  add(t);
  add(...A, t);
  add(t, ...A);
}

// --- Unicode decimal digits in float() ---
const digitProbes = [
  '١٢٣',            // Arabic-Indic 123
  '1٢',                        // mixed ASCII + Arabic-Indic
  '１２',                   // fullwidth
  '๑๒',                   // Thai
  '۱۲',                   // Extended Arabic-Indic
  '၀1၀',                  // Myanmar-ish (deliberately odd)
  '०१',                   // Devanagari
  '\u{1D7CE}\u{1D7D8}',             // Mathematical bold zero + double-struck zero
  '١.٥',                  // Arabic-Indic with ASCII point
  '١e٢',                  // Arabic-Indic mantissa + exponent
  '٫1',                        // Arabic decimal separator (rejected)
  '．5',                        // fullwidth full stop (rejected)
];
for (const v of digitProbes) {
