  add('--amount1', `1.5${w}`, '--amount2', '999', '--currency', 'USD');
  add('--amount1', `${w}1.5${w}`, '--amount2', '999', '--currency', 'USD');
  add('--amount1', w, '--amount2', '999', '--currency', 'USD');
}

