                 '--5', '-1e5', '-1e-5', '-inf', '-nan', '-', '- X', '-1e5 ', ' -1e5', '',
                 '-Infinity', '-0.0']) {
  add('--amount1', v, '--amount2', '999', '--currency', 'USD');
  add(`--amount1=${v}`, '--amount2', '999', '--currency', 'USD');
  add('--amount1', '1', '--amount2', '999', '--currency', v);
}

