/**
 * A minimal exact-decimal type matching the subset of `decimal.Decimal`
 * that the reference program exercises.
 *
 * A value is `(-1)^negative * digits * 10^exp`, with `digits` an unsigned digit
 * string carrying no leading zeros. All arithmetic here is string/integer based:
 * no BigInt, no floating point, so results are exact at any magnitude.
 */
import { InvalidOperation } from './errors.mjs';

/** `decimal.getcontext().prec` — CPython's default context precision. */
export const CONTEXT_PRECISION = 28;

const NAN = Object.freeze({ special: 'nan', negative: false, digits: '0', exp: 0 });

function makeInfinity(negative) {
  return Object.freeze({ special: 'inf', negative, digits: '0', exp: 0 });
}

/** Drop leading zeros, collapsing an all-zero string to a single "0". */
function stripLeadingZeros(s) {
  let i = 0;
  while (i < s.length - 1 && s[i] === '0') i++;
  return s.slice(i);
}

/** Add one to an unsigned digit string, growing it on carry-out. */
function incrementDigits(s) {
  const out = s.split('');
  let i = out.length - 1;
  for (; i >= 0; i--) {
    if (out[i] === '9') {
      out[i] = '0';
    } else {
      out[i] = String.fromCharCode(out[i].charCodeAt(0) + 1);
      return out.join('');
    }
  }
  return '1' + out.join('');
}

/**
 * Divide the unsigned digit string `s` by 10^shift, rounding ROUND_HALF_EVEN.
 * A non-positive `shift` multiplies instead, which is always exact.
 */
function shiftRoundHalfEven(s, shift) {
  if (shift <= 0) return s + '0'.repeat(-shift);

  // Guarantee at least one surviving digit so the tie-break has a digit to inspect.
  const padded = s.length > shift ? s : '0'.repeat(shift - s.length + 1) + s;
  const keep = padded.slice(0, padded.length - shift);
  const dropped = padded.slice(padded.length - shift);

  const lead = dropped.charCodeAt(0) - 48;
  let roundUp;
  if (lead > 5) {
    roundUp = true;
  } else if (lead < 5) {
    roundUp = false;
  } else {
    let restNonZero = false;
    for (let i = 1; i < dropped.length; i++) {
      if (dropped.charCodeAt(i) !== 48) {
        restNonZero = true;
        break;
      }
    }
    // Exact tie: round to even. Otherwise the remainder pushes it up.
    roundUp = restNonZero || (keep.charCodeAt(keep.length - 1) - 48) % 2 === 1;
  }
  return roundUp ? incrementDigits(keep) : keep;
}

/**
 * Build the Decimal that `Decimal(str(x))` produces for a Python float `x`.
 *
 * py-moneyed stringifies the float before handing it to Decimal, so the value is
 * the *shortest round-tripping decimal* rather than the exact binary expansion —
 * `1e23` becomes 10^23, not 99999999999999991611392. JavaScript's `String(Number)`
 * yields those same shortest-round-trip digits; only its choice of when to switch
 * to exponent notation differs from Python's, and that is purely cosmetic here
 * because we immediately decompose the text into digits and an exponent.
 */
export function decimalFromNumber(x) {
  if (Number.isNaN(x)) return NAN;
  if (x === Infinity) return makeInfinity(false);
  if (x === -Infinity) return makeInfinity(true);

  // Object.is separates -0.0 from 0.0; Decimal keeps that sign, and babel reads it.
  const negative = x < 0 || Object.is(x, -0);
  const text = String(Math.abs(x));

  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]\d+))?$/.exec(text);
  const intPart = m[1];
  const fracPart = m[2] || '';
  const expPart = m[3] ? Number(m[3]) : 0;

  return {
    special: null,
    negative,
    digits: stripLeadingZeros(intPart + fracPart),
    exp: expPart - fracPart.length,
  };
}

/** True when the value carries a minus sign — including negative zero. */
export function isSigned(d) {
  return d.negative;
}

export function isNaNDecimal(d) {
  return d.special === 'nan';
}

export function isInfinite(d) {
  return d.special === 'inf';
}

function isZero(d) {
  return d.special === null && d.digits === '0';
}

/** Compare magnitudes of two finite decimals: -1, 0 or 1. */
function compareMagnitude(a, b) {
  const aZero = a.digits === '0';
  const bZero = b.digits === '0';
  if (aZero || bZero) return aZero && bZero ? 0 : aZero ? -1 : 1;

  // Position of the most significant digit relative to the decimal point.
  const aAdj = a.digits.length + a.exp;
  const bAdj = b.digits.length + b.exp;
  if (aAdj !== bAdj) return aAdj < bAdj ? -1 : 1;

  const width = Math.max(a.digits.length, b.digits.length);
  const aPad = a.digits.padEnd(width, '0');
  const bPad = b.digits.padEnd(width, '0');
  if (aPad === bPad) return 0;
  return aPad < bPad ? -1 : 1;
}

/**
 * Total ordering over Decimals, matching `decimal.Decimal.__lt__` and friends.
 * Comparing a NaN raises InvalidOperation, exactly as CPython's context does.
 */
export function compare(a, b) {
  if (a.special === 'nan' || b.special === 'nan') throw new InvalidOperation();

  const aSign = a.special === 'inf' ? (a.negative ? -1 : 1) : isZero(a) ? 0 : a.negative ? -1 : 1;
  const bSign = b.special === 'inf' ? (b.negative ? -1 : 1) : isZero(b) ? 0 : b.negative ? -1 : 1;
  if (aSign !== bSign) return aSign < bSign ? -1 : 1;

  if (a.special === 'inf' || b.special === 'inf') {
    if (a.special === 'inf' && b.special === 'inf') return 0;
    // Same sign, one infinite: the infinite one is further from zero.
    const infIsA = a.special === 'inf';
    if (aSign > 0) return infIsA ? 1 : -1;
    return infIsA ? -1 : 1;
  }

  const mag = compareMagnitude(a, b);
  return aSign < 0 ? -mag : mag;
}

/**
 * Quantize |d| to exactly `places` fraction digits using ROUND_HALF_EVEN, and
 * return the resulting coefficient as an unsigned digit string.
 *
 * `Decimal.quantize` raises InvalidOperation when the resulting coefficient is
 * longer than the context precision, which is what makes the reference program
 * die on inputs like `1e26` in USD (27 integer digits + 2 fraction digits = 29).
 */
export function quantizeCoefficient(d, places) {
  const shift = -(d.exp + places);
  const coefficient = stripLeadingZeros(shiftRoundHalfEven(d.digits, shift));
  if (coefficient.length > CONTEXT_PRECISION) throw new InvalidOperation();
  return coefficient;
}

