import { execFile } from 'node:child_process';

// Usage-wrapping must track COLUMNS the way shutil.get_terminal_size does.
const WIDTHS = ['', '1', '10', '20', '30', '40', '50', '60', '70', '76', '77', '78', '79',
                '80', '81', '90', '100', '120', '200', '0', '-5', 'abc'];
const ARGVS = [
  ['--help'],
  ['-h'],
  [],
  ['--amount1', '1'],
  ['--amount1', 'abc', '--amount2', '2', '--currency', 'USD'],
  ['--amount1', '1', '--amount2', '2', '--currency', 'USD', 'extra'],
  ['--am', '1'],
];

const run = (cmd, argv, columns) => new Promise(res => {
  const env = { ...process.env, LANG: 'en_US.UTF-8', LC_ALL: 'en_US.UTF-8' };
  if (columns === '') delete env.COLUMNS; else env.COLUMNS = columns;
  execFile(cmd, argv, { env, encoding: 'buffer' }, (e, so, se) =>
    res({ code: e ? (e.code ?? 0) : 0, out: so.toString(), err: se.toString() }));
});

let bad = 0, total = 0;
for (const columns of WIDTHS) {
  for (const argv of ARGVS) {
    const [py, js] = await Promise.all([
      run('/workspace/dataset/test19_executable', argv, columns),
      run(process.execPath, ['/output/test19.mjs', ...argv], columns),
    ]);
    total++;
    if (py.out !== js.out || py.err !== js.err || py.code !== js.code) {
      bad++;
      console.log(`\nCOLUMNS=${JSON.stringify(columns)} argv=${JSON.stringify(argv)}`);
      console.log('  py:', JSON.stringify(py));
      console.log('  js:', JSON.stringify(js));
    }
  }
}
console.log(`\nCOLUMNS matrix: ${total} cases, ${bad} mismatches`);

